def morse_encode(text):
    morse = {'s': '...', 'o': '---'}
    return ' '.join(morse.get(c.lower(), '') for c in text if c.isalpha())

def morse_decode(code):
    morse = {'...': 's', '---': 'o'}
    words = code.split()
    return ''.join(morse.get(w, '') for w in words)

