def encrypt_caesar(plaintext: str, shift: int) -> str:
    return ''.join(
        chr(((ord(c) - 65 + shift) % 26) + 65) if 'A' <= c <= 'Z' else c
        for c in plaintext.upper()
    )

def decrypt_caesar(ciphertext: str, shift: int) -> str:
    return ''.join(
        chr(((ord(c) - 65 - shift) % 26) + 65) if 'A' <= c <= 'Z' else c
        for c in ciphertext.upper()
    )

