def move_snake(snake: list[tuple[int, int]], direction: tuple[int, int]) -> list[tuple[int, int]]:
    head = snake[0]
    x, y = direction
    new_head = (head[0] + x, head[1] + y)
    return snake[:1] + [new_head] + snake[1:-1]

def check_collision(snake: list[tuple[int, int]], food: tuple[int, int]) -> bool:
    if snake[0] in snake[1:]:
        return True
    if snake[0][0] < 0 or snake[0][0] >= 10 or snake[0][1] < 0 or snake[0][1] >= 10:
        return True
    return snake[0] == food

