    const minutes = Math.floor(secondsRemaining / 60);
    const seconds = secondsRemaining % 60;
    document.getElementById('counter')!.textContent = `${minutes}:${String(seconds).padStart(2, '0')}`;
    secondsRemaining--;
  }, 1000);
