import xor_util as xu

def train_xor(nnet, epochs):
    for epoch in range(epochs):
        for x, y in xu.XOR_DATA:
            nnet.forward(x)
            nnet.backward(x, y)
            nnet.update_weights()

def evaluate_xor(nnet):
    results = {}
    for x in xu.XOR_DATA:
        output = nnet.forward(x)
        results[str(x)] = round(output[0], 1)
    return results

class MLP:
    def __init__(self):
        self.layers = [xu.Layer(2, 2, xu.sigmoid, xu.d_sigmoid), xu.Layer(2, 1, xu.sigmoid, xu.d_sigmoid)]

    def forward(self, input):
        self.layers[0].input = input
        self.layers[0].activate()
        self.layers[1].input = self.layers[0].output
        self.layers[1].activate()
        return self.layers[1].output

    def backward(self, input, target):
        self.forward(input)
        self.layers[1].error = target - self.layers[1].output
        self.layers[1].delta = self.layers[1].error * self.layers[1].d_activation(self.layers[1].input)
        self.layers[0].error = self.layers[1].delta.dot(self.layers[1].weights.T)
        self.layers[0].delta = self.layers[0].error * self.layers[0].d_activation(self.layers[0].input)
        self.layers[0].update_weights(self.layers[0].delta, self.layers[0].input)
        self.layers[1].update_weights(self.layers[1].delta, self.layers[0].output)

    def update_weights(self, delta, prev_layer_output):
        self.layers[1].weights += self.layers[1].learning_rate * delta * prev_layer_output
        self.layers[1].bias += self.layers[1].learning_rate * delta
        self.layers[0].weights += self.layers[0].learning_rate * self.layers[0].delta * self.layers[0].input
        self.layers[0].bias += self.layers[0].learning_rate * self.layers[0].delta

def main():
    xor_net = MLP()
    train_xor(xor_net, 500)
    results = evaluate_xor(xor_net)
    for key, value in results.items():
        print(f'{key}: {value}')

if __name__ == '__main__':
    main()

def sigmoid(z: float) -> float:
    return 1 / (1 + math.exp(-z))

def d_sigmoid(z: float) -> float:
    s = sigmoid(z)
    return s * (1 - s)

