export interface Move { row: number; col: number }
export class Game {
  private board: string[][];
  constructor() { this.board = Array.from({ length: 3 }, () => new Array(3).fill('')); }
  private checkVictory() {
    const lines = [
      this.board[0],
      this.board[1],
      this.board[2],
      this.board[0][0] + this.board[1][0] + this.board[2][0],
      this.board[0][1] + this.board[1][1] + this.board[2][1],
      this.board[0][2] + this.board[1][2] + this.board[2][2],
      this.board[0][0] + this.board[1][1] + this.board[2][2],
      this.board[0][2] + this.board[1][1] + this.board[2][0],
    ];
    return lines.some((line) => (line.includes('X') && line.includes('O') ? null : line.includes('X') ? 'X' : line.includes('O') ? 'O' : null));
  }
  get availableMoves() { return this.board.map((row, i) => row.map((cell, j) => cell === '' ? { row: i, col: j } : null).filter(Boolean)).flat(); }
  move(row: number, col: number, player: 'X' | 'O') {
    if (this.board[row][col] !== '') return false;
    this.board[row][col] = player;
    return this.checkVictory();
  }
}
export function minimax(board: string[][], depth: number, isMaximizing: boolean, player: 'X' | 'O', alpha: number, beta: number) {
  const winner = board.find((row) => row.every((cell) => cell === player));
  if (winner) return isMaximizing ? 10 : -10;
  if (!board.some((row) => row.some((cell) => cell === ''))) return 0;
  let value = -Infinity;
  for (const { row, col } of new Game().availableMoves) {
    board[row][col] = player;
    const score = minimax(board, depth - 1, !isMaximizing, player === 'X' ? 'O' : 'X', alpha, beta);
    board[row][col] = '';
    value = Math.max(value, score);
    alpha = Math.max(alpha, value);
    if (beta <= alpha) break;
  }
  return value;
}

export class TicTacToe {
  private game: Game;
  private status: string;
  private board: string[] = new Array(9).fill('');
  private currentPlayer: 'x' | 'o';

  constructor() {
    this.game = new Game();
    this.status = 'Your turn';
    this.currentPlayer = 'x';
  }

  handleCellClick(index: number): void {
    if (this.board[index] || this.game.isGameOver()) return;
    this.board[index] = this.currentPlayer;
    this.currentPlayer = this.currentPlayer === 'x' ? 'o' : 'x';
    this.game.update(this.board);
    if (this.game.isGameOver()) {
      this.status = this.game.getWinner() === '' ? 'Draw' : `Player ${this.game.getWinner()} wins!`;
      this.board.fill('');
      this.currentPlayer = 'x';
    } else {
      if (this.currentPlayer === 'o') {
        const move = this.game.minimax(this.board);
        this.board[move] = 'o';
        this.currentPlayer = 'x';
      }
    }
  }

  getBoard(): string[] { return this.board; }
  getStatus(): string { return this.status; }
}

export function gameLoop(snake, food, canvas) {
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'var(--snake-color)';
  snake.forEach((s) => {
    ctx.fillRect(s.x * 20, s.y * 20, 20, 20);
  });
  ctx.fillStyle = 'var(--food)';
  ctx.fillRect(food.x * 20, food.y * 20, 20, 20);
  ctx.fillStyle = 'var(--line)';
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(canvas.width, 0);
  ctx.lineTo(canvas.width, canvas.height);
  ctx.lineTo(0, canvas.height);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'var(--line)';
  ctx.strokeRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = 'var(--border)';
  ctx.strokeRect(0, 0, canvas.width, canvas.height);
}

import { gameLoop } from './game-loop.js';

let snake = [{ x: 10, y: 10 }], direction = { x: 1, y: 0 }, food = { x: 15, y: 15 }, score = 0, canvas;

function handleInput(e) {
  switch (e.key) {
    case 'ArrowUp': direction = { x: 0, y: -1 }; break;
    case 'ArrowDown': direction = { x: 0, y: 1 }; break;
    case 'ArrowLeft': direction = { x: -1, y: 0 }; break;
    case 'ArrowRight': direction = { x: 1, y: 0 }; break;
  }
}

function moveSnake() {
  snake.push({ x: snake[0].x + direction.x, y: snake[0].y + direction.y });
  if (snake[0].x < 0 || snake[0].x >= 20 || snake[0].y < 0 || snake[0].y >= 20) {
    snake[0] = { x: 10, y: 10 };
    snake.splice(1);
  }
  if (snake[0].x === food.x && snake[0].y === food.y) {
    score += 1;
    food = { x: Math.floor(Math.random() * 20), y: Math.floor(Math.random() * 20) };
    snake.push({ x: snake[snake.length - 1].x + direction.x, y: snake[snake.length - 1].y + direction.y });
  } else {
    snake.splice(0, 1);
  }
}

function draw() {
  gameLoop(snake, food, canvas);
}

function checkCollisions() {
  for (let i = 1; i < snake.length; i++) {
    if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
      return true;
    }
  }
  return false;
}

export function startGame(canvasEl) {
  canvas = canvasEl;
  canvas.width = 400;
  canvas.height = 400;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'var(--bg)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const scoreDisplay = document.getElementById('score');
  const gameScore = document.getElementById('game-score');
  const gameOver = document.getElementById('game-over');
  const gameCanvas = document.getElementById('game-canvas');
  gameCanvas.addEventListener('keydown', handleInput);
  let intervalId = null;
  function gameTick() {
    moveSnake();
    if (checkCollisions()) {
      clearInterval(intervalId);
      gameOver.style.display = 'block';
      gameScore.textContent = 'Score: ' + score;
    } else {
      draw();
    }
  }
  intervalId = setInterval(gameTick, 100);
}

