  private ball: Ball;
  private bricks: Brick[];
  private lives: number;
  constructor(canvas: HTMLCanvasElement, paddle: Paddle, ball: Ball, bricks: Brick[], lives: number) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d')!;
    this.paddle = paddle;
    this.ball = ball;
    this.bricks = bricks;
    this.lives = lives;
  }
  private clear() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
  }
  private drawPaddle() {
    this.ctx.fillStyle = '#0095DD';
    this.ctx.fillRect(this.paddle.x, this.paddle.y, this.paddle.width, this.paddle.height);
  }
  private drawBall() {
    this.ctx.fillStyle = '#F2994A';
    this.ctx.beginPath();
    this.ctx.arc(this.ball.x, this.ball.y, this.ball.r, 0, Math.PI * 2);
    this.ctx.fill();
  }
  private drawBricks() {
    for (const brick of this.bricks) {
      this.ctx.fillStyle = brick.color;
      this.ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
    }
  }
  private drawLives() {
    this.ctx.fillStyle = '#FF0000';
    this.ctx.font = '20px Arial';
    this.ctx.fillText(`Lives: ${this.lives}`, 10, 30);
  }
  private checkCollision() {
    const ballRect = this.ball.getBoundingRect();
    for (const brick of this.bricks) {
      if (ballRect.intersects(brick)) return true;
    }
    return false;
  }
  private updateState() {
    this.paddle.update();
    this.ball.update();
    if (this.ball.y > this.canvas.height) { this.lives--; if (this.lives <= 0) return 'game-over'; }
    if (this.checkCollision()) { this.ball.reflectY(); }
  }
  private draw() {
    this.clear();
    this.drawPaddle();
    this.drawBall();
    this.drawBricks();
    this.drawLives();
  }
  public start() {
    this.updateState();
    this.draw();
  }
}

export function getKeyState(): Record<'left' | 'right' | 'up' | 'down', boolean> {
  const keys = { left: false, right: false, up: false, down: false };
  if (document) {
    const active = document.activeElement as Element | null;
    if (active?.tagName !== 'BODY') return keys;
    const paddle = document.querySelector('#paddle') as HTMLElement;
    if (paddle) {
      keys.left = paddle.offsetLeft <= active.offsetLeft;
      keys.right = paddle.offsetLeft + paddle.offsetWidth >= active.offsetLeft + active.offsetWidth;
    }
  }
  return keys;
}

export function runCommand(command: string): { ok: boolean; result: string; error?: string } {
  const parts = command.trim().split(' ');
  if (!parts.length) return { ok: false, result: '', error: 'No command provided' };
  const cmd = parts[0].toLowerCase();
  let out = '';
  try {
    switch (cmd) {
      case 'help':
        out = 'Available commands:\n' +
          '  help: List available commands\n' +
          '  ls: List directory contents\n' +
          '  cd: Change directory\n' +
          '  echo: Echo a string\n' +
          '  clear: Clear the screen\n' +
          '  about: Show information about the system';
        break;
      case 'ls': {
        out = 'No files in current directory';
        break;
      }
      case 'cd':
        out = 'cd: Not implemented';
        break;
      case 'echo':
        if (parts.length < 2) return { ok: false, result: '', error: 'Usage: echo <message>' };
        out = parts.slice(1).join(' ');
        break;
      case 'clear':
        out = '';
        break;
      case 'about':
        out = 'Terminal OS Simulator\nVersion: 1.0.0\nPowered by: TypeScript';
        break;
      default:
        out = 'Unknown command';
    }
  } catch (e) {
    out = `Error: ${e}`;
  }
  return { ok: true, result: out };
}

export function renderTerminal(commands: Command[]) {
  const lines = commands.map((c) => {
    if (c.error) return `>>> ${c.command} ${c.error}`;
    return `>>> ${c.command}`;
  });
  return lines.join('\n');
}

export function LineChart(canvas: HTMLCanvasElement, data: number[], options?: { xLabel: string; yLabel: string; width?: number; height?: number }) {
  const ctx = canvas.getContext('2d')!;
  const w = options?.width ?? 400;
  const h = options?.height ?? 300;
  canvas.width = w;
  canvas.height = h;

  const max = Math.max(...data);
  const min = Math.min(...data);
  const scale = (h - 50) / (max - min);

  ctx.clearRect(0, 0, w, h);

  const draw = (x: number, y: number, label?: string) => {
    ctx.beginPath();
    ctx.moveTo(x, h - 50);
    ctx.lineTo(x, h - 50 - y * scale);
    ctx.stroke();
    if (label) ctx.fillText(label, x, h - 45 - y * scale);
  };

  const line = data.map((v, i) => ({ x: (i + 1) * (w / (data.length + 1)), y: v }));
  for (let i = 1; i < line.length; i++) {
    draw(line[i - 1].x, line[i - 1].y, String(line[i - 1].y.toFixed(2)));
    draw(line[i].x, line[i].y);
    ctx.beginPath();
    ctx.moveTo(line[i - 1].x, h - 50 - line[i - 1].y * scale);
    ctx.lineTo(line[i].x, h - 50 - line[i].y * scale);
    ctx.stroke();
  }

  ctx.font = '12px Arial';
  ctx.fillText(options?.xLabel ?? '', 10, h - 30);
  ctx.fillText(options?.yLabel ?? '', w - 50, h - 50);
}

