export class Game {
  private cells: boolean[][] = [];
  private rows: number = 20;
  private cols: number = 20;
  private width: number = 300;
  private height: number = 300;
  private cellsPerRow: number;

  constructor(rows: number, cols: number) {
    this.rows = rows;
    this.cols = cols;
    this.width = cols * 15;
    this.height = rows * 15;
    this.cellsPerRow = cols;
    this.cells = Array.from({ length: rows }, () => Array(cols).fill(false));
  }

  updateCells() {
    const nextCells = this.cells.map((row) => [...row]);
    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        const neighbors = this.getNeighborCount(row, col);
        if (this.cells[row][col]) {
          if (neighbors < 2 || neighbors > 3) nextCells[row][col] = false;
        } else if (neighbors === 3) nextCells[row][col] = true;
      }
    }
    this.cells = nextCells;
  }

  getNeighborCount(row: number, col: number): number {
    let count = 0;
    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        const r = row + dr, c = col + dc;
        if (r >= 0 && r < this.rows && c >= 0 && c < this.cols) count += this.cells[r][c] ? 1 : 0;
      }
    }
    return count;
  }

  get cellsPerRow() { return this.cellsPerRow; }
  get rows() { return this.rows; }
  get cols() { return this.cols; }
  get width() { return this.width; }
  get height() { return this.height; }
  get cellsData() { return this.cells; }
}

